            ):
                exposure += _number(order.get("TOT_AMT"))

        limit = _number(account.get("CRED_LIMIT"))
        hold = account.get("CRED_HOLD")

        if exposure > limit and hold != "Y":
            account["CRED_HOLD"] = "Y"
            audits.append(("CRED_HOLD_ON", acct_id))

        if exposure <= limit * Decimal(8) / Decimal(10) and account.get("CRED_HOLD") == "Y":
            account["CRED_HOLD"] = "N"
            audits.append(("CRED_HOLD_OFF", acct_id))

    return new_accounts, audits
